class Base {
    Base() {
        show();
    }
    void show() {
        System.out.println("Base");
    }
}
class Derived extends Base {
    int value = 7;
    void show() {
        System.out.println("value=" + value);
    }
}
public class Main {
    public static void main(String[] args) {
        Derived d = new Derived();
        d.show();
    }
}
